<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { getSale } from '../api'; import type { SaleReceipt } from '../types'; import ReturnDialog from '../../returns/components/ReturnDialog.vue'; import type { ReturnReceipt } from '../../returns/types'; import ReceiptDialog from '../components/ReceiptDialog.vue'; import { errorMessage } from '../../catalog/api'
const route=useRoute(),sale=ref<SaleReceipt|null>(null),alert=ref(''),returnOpen=ref(false),receiptOpen=ref(false),success=ref('')
async function load(){try{sale.value=await getSale(String(route.params.id))}catch(cause){alert.value=errorMessage(cause)}}
async function returned(receipt:ReturnReceipt){success.value=`退货成功：${receipt.orderNo}，退款 ¥${receipt.refundAmount.toFixed(2)}`;returnOpen.value=false;await load()}onMounted(load)
</script>
<template><main class="page"><RouterLink to="/sales/history">← 返回销售记录</RouterLink><p v-if="alert" role="alert">{{alert}}</p><template v-if="sale"><header><div><h1>{{sale.orderNo}}</h1><p>{{sale.occurredAt}} · {{sale.status}}</p></div><div><button @click="receiptOpen=true">补打小票</button><button :disabled="sale.status==='RETURNED'" @click="returnOpen=true">原单退货</button></div></header><p v-if="success" role="status" class="success">{{success}}</p><section class="card"><table><thead><tr><th>SKU</th><th>数量</th><th>已退</th><th>成交金额</th></tr></thead><tbody><tr v-for="line in sale.lines" :key="line.id"><td>{{line.skuCode}}</td><td>{{line.quantity}}</td><td>{{line.returnedQuantity}}</td><td>¥{{line.actualAmount.toFixed(2)}}</td></tr></tbody></table><p class="amount">实收 ¥{{sale.actualAmount.toFixed(2)}}</p></section><ReturnDialog :open="returnOpen" :sale="sale" @close="returnOpen=false" @success="returned"/><ReceiptDialog :receipt="receiptOpen?sale:null" @close="receiptOpen=false"/></template></main></template>
<style scoped>.page{display:grid;gap:1rem;max-width:78rem;margin:auto}header{display:flex;justify-content:space-between;align-items:center}header button{margin-left:.5rem;padding:.65rem}.card{background:#fff;border:1px solid #e2e8f0;border-radius:.8rem;padding:1rem}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;border-bottom:1px solid #e2e8f0;text-align:left}.amount{text-align:right;font-size:1.4rem;font-weight:800}.success{color:#166534;background:#f0fdf4;padding:.7rem}</style>
